fields.InputDefinition:
{
  "goal": "Open the 'Members' entity grid — type 'Members' in the LEFT sidebar 'Search entities...' box and click the EXACT 'Members' match (not 'Board Members'/'Memberships'); if that is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Members. The grid loads ~100 of ~2,002 records per page. Type a value into the grid's filter box (placeholder 'Filter records...') — e.g. a common first-name fragment — and verify the grid RESPONDS to the filter: the displayed rows narrow to matching ones, OR a clear 'No Matching Rows' state appears if none match on the loaded page. Either response confirms the filter is functional (it is client-side over the loaded page). Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 45,
  "judgeValidationCriteria": [
    "The Members entity grid is displayed with rows",
    "The grid responded to filter input (rows narrowed to matches, or a clear no-match state was shown)",
    "No error messages, blank screens, or crash pages"
  ]
}
